import {done,taskStatus,person,project,activeIssue,tasksFor,STAGES} from './model.js';
import {taskDefaults,selectableProjects,isClosedProject,issueRole} from './workflow-rules.js';

export function createSimpleUI(ctx){
 const {ui,esc,button,badge,field,selectField,showDrawer,closeDrawer,formSubmit,operation,render,header,panel,tabs,stat,empty,date,historyView,editAllowed}=ctx;
 const $=q=>document.querySelector(q),state=()=>ctx.getState(),name=id=>person(state(),id)?.name||'Unassigned';
 ui.workProject='';ui.workQuery='';ui.workLimit=10;
 let pickers=new Map(),taskDraft=null,peopleScope='team';
 const closedHint=p=>isClosedProject(p)?`<span class="pill amber">${esc(p.lifecycle)} project · outstanding work</span>`:'';
 const inputValues=key=>[...document.querySelectorAll(`[data-picker="${key}"] input[data-value]`)].map(x=>x.value);
 function lookup(label,key,items,values=[],{multiple=false,preferred=[],emptyText='Search to choose',change=null}={}){
  pickers.set(key,{items,values:[...values],multiple,preferred,change});
  return `<div class="field lookup" data-picker="${key}"><label>${esc(label)}</label><div data-selection>${selection(key)}</div><details class="lookup-menu"><summary>${esc(emptyText)}</summary><input class="lookup-search" data-lookup="${key}" type="search" placeholder="Search by name or ID" aria-label="Search ${esc(label)}" autocomplete="off"><div data-results>${lookupResults(key,'')}</div></details></div>`;
 }
 function selection(key){const p=pickers.get(key);return `${p.values.map(v=>`<input type="hidden" data-value name="${key}" value="${esc(v)}">`).join('')}<div class="selected-values">${p.values.length?p.values.map(v=>`<span class="selected-chip">${esc(p.items.find(x=>x.id===v)?.label||v)}${p.multiple?button('×','lookup-remove',key+'|'+v,'quiet'):''}</span>`).join(''):'<span class="muted small">Unassigned</span>'}</div>`;}
 function lookupResults(key,query){const p=pickers.get(key),q=query.trim().toLowerCase();let found=p.items.filter(x=>!p.values.includes(x.id)&&(!q||`${x.label} ${x.detail||''} ${x.id}`.toLowerCase().includes(q)));if(!q&&p.preferred.length)found=found.filter(x=>p.preferred.includes(x.id));return `${found.slice(0,15).map(x=>`<button type="button" class="lookup-result" data-action="lookup-select" data-id="${esc(key+'|'+x.id)}"><strong>${esc(x.label)}</strong><small>${esc(x.detail||'')}</small></button>`).join('')||'<p class="small muted">No matches. Try another name or ID.</p>'}<p class="lookup-count">${Math.min(15,found.length)} of ${found.length}${found.length>15?' · Keep typing to narrow the list':''}</p>`;}
 function updateLookup(key){const node=$(`[data-picker="${key}"]`);if(!node)return;node.querySelector('[data-selection]').innerHTML=selection(key);const query=node.querySelector('.lookup-search').value;node.querySelector('[data-results]').innerHTML=lookupResults(key,query);}
 function peopleItems(){return state().people.map(p=>({id:p.id,label:p.name,detail:`${p.department}${p.email?' · '+p.email:''}`}));}
 function projectItems(ps){return ps.map(p=>({id:p.id,label:`${p.id} · ${p.name}`,detail:`${p.lifecycle||'Active'} · ${name(p.leadId)}`}));}
 function teamIds(pid,selected=[]){const p=project(state(),pid);return [...new Set([...(p?.team||[]),p?.leadId,...selected].filter(Boolean))];}
 function currentProjects(){return selectableProjects(state(),ui.person);}
 function displayTaskList(ts){return ts.length?`<div class="work-list">${ts.map(t=>{
  const mine=t.completedBy.includes(ui.person),p=project(state(),t.projectId);return `<article class="work-row"><button type="button" class="check ${mine?'checked':''}" data-action="confirm-task" data-id="${esc(t.id)}" aria-label="${mine?'Undo confirmation':'Confirm my part'}: ${esc(t.title)}" ${!editAllowed()?'disabled':''}>${mine?'✓':''}</button><div class="work-description">${button(t.title,'task',t.id,'link work-title')}<div class="work-context">${esc(t.projectId)} · ${esc(p?.name)}${closedHint(p)}</div>${mine&&!done(t)?'<span class="small muted">Your part is complete · waiting for other owners</span>':''}</div><div class="work-timing"><span class="${!done(t)&&t.due<state().scenarioDate?'due-red':''}">${date(t.due)}</span>${badge(taskStatus(t,state().scenarioDate))}</div>${button('Update','task',t.id,'work-update')}</article>`;}).join('')}</div>`:empty('You are up to date in this view.');}
 function myIssues(items){return items.length?items.slice(0,ui.issueLimit||6).map(i=>{const r=issueRole(state(),i,ui.person);return `<article class="issue-mini"><div class="row wrap">${badge(i.severity)}<span class="small muted">${esc(i.projectId)}</span></div><p>${button(i.title,'issue',i.id,'link')}</p><p class="small muted">${esc(r.label)}</p><div class="row wrap">${badge(i.status)}${button(r.button,r.action,r.id||i.id,'quiet')}</div></article>`;}).join('')+(items.length>(ui.issueLimit||6)?`<div class="list-footer">${button(`Show more (${items.length-(ui.issueLimit||6)})`,'more-issues')}</div>`:''):empty('No issues need your attention.');}
 function renderMyWork(){
  const s=state(),mine=s.tasks.filter(t=>t.ownerIds.includes(ui.person)),mineIds=new Set(mine.map(t=>t.id));
  const match=(pid,title='')=>(!ui.workProject||pid===ui.workProject)&&(!ui.workQuery||`${title} ${pid} ${project(s,pid)?.name}`.toLowerCase().includes(ui.workQuery.toLowerCase()));
  const open=mine.filter(t=>!done(t)),personal=open.filter(t=>!t.completedBy.includes(ui.person));
  let ts=mine.filter(t=>(ui.personalTab==='completed'?t.completedBy.includes(ui.person):ui.personalTab==='all'?!done(t):!done(t)&&!t.completedBy.includes(ui.person)&&t.due<=s.scenarioDate)&&match(t.projectId,t.title));
  ts.sort((a,b)=>Number(b.priority==='High')-Number(a.priority==='High')||a.due.localeCompare(b.due)||a.title.localeCompare(b.title));
  const acts=s.actions.filter(a=>a.ownerId===ui.person&&!['Done','Cancelled'].includes(a.status)&&activeIssue(s.issues.find(i=>i.id===a.issueId))&&match(s.issues.find(i=>i.id===a.issueId).projectId,a.title)).sort((a,b)=>a.due.localeCompare(b.due));
  const actionIssues=new Set(acts.map(a=>a.issueId));
  const issues=s.issues.filter(i=>activeIssue(i)&&match(i.projectId,i.title)&&(i.ownerId===ui.person||project(s,i.projectId)?.leadId===ui.person||i.verifierId===ui.person||actionIssues.has(i.id)||i.relatedTaskIds.some(id=>mineIds.has(id)))).sort((a,b)=>Number(b.status==='Pending Verification')-Number(a.status==='Pending Verification')||['Critical','High','Medium','Low'].indexOf(a.severity)-['Critical','High','Medium','Low'].indexOf(b.severity));
  return header(`Good morning, ${name(ui.person).split(' ')[0]}`,`${person(s,ui.person).department} · ${personal.length} tasks waiting for you across ${new Set(personal.map(t=>t.projectId)).size} projects`,editAllowed()?button('Add task','new-task','','primary','plus'):'')+`<div class="stats">${stat('To do',personal.length,'Your outstanding work')}${stat('Overdue',personal.filter(t=>t.due<s.scenarioDate).length,'Across your projects','red')}${stat('Recovery actions',s.actions.filter(a=>a.ownerId===ui.person&&!['Done','Cancelled'].includes(a.status)&&activeIssue(s.issues.find(i=>i.id===a.issueId))).length,'Separate from the project plan','amber')}${stat('Waiting for you',s.issues.filter(i=>i.status==='Pending Verification'&&(i.verifierId||project(s,i.projectId)?.leadId)===ui.person).length,'Issue resolution checks')}</div><div class="work-toolbar"><div>${tabs([['today','Needs attention'],['all','All open'],['completed','My completed work']],ui.personalTab,'personal-tab')}</div><div class="row"><input id="mywork-search" type="search" aria-label="Search my tasks and projects" placeholder="Search task or project" value="${esc(ui.workQuery)}">${button(ui.workProject?ui.workProject:'All my projects','work-projects','','quiet')}${ui.workProject?button('Clear','clear-work-project','','quiet'):''}</div></div><div class="two-col"><div>${acts.length?`<div class="action-jump">${button(`${acts.length} recovery actions to update`,'jump-actions','','quiet')}</div>`:''}${panel('Your tasks',displayTaskList(ts.slice(0,ui.workLimit))+(ts.length>ui.workLimit?`<div class="list-footer">${button(`Show next ${Math.min(10,ts.length-ui.workLimit)}`,'more-work')}<span class="small muted">${ui.workLimit} of ${ts.length}</span></div>`:''),`<span class="small muted">${ts.length} matching tasks</span>`)}${acts.length?panel('Your recovery actions',`<div class="work-list">${acts.slice(0,ui.actionLimit||8).map(a=>`<article class="work-row"><div class="work-description">${button(a.title,'action',a.id,'link work-title')}<div class="work-context">${esc(s.issues.find(i=>i.id===a.issueId).title)}</div></div><span class="small">${date(a.due)}</span>${button('Update','action',a.id)}</article>`).join('')}</div>`+(acts.length>(ui.actionLimit||8)?`<div class="list-footer">${button('Show more actions','more-actions')}</div>`:'')):''}</div><div>${panel('Issues needing your attention',myIssues(issues))}</div></div>`;
 }
 function openPeople(){
  peopleScope='team';const ps=currentProjects(),team=new Set([ui.person,'sun',...ps.flatMap(p=>teamIds(p.id))]);
  showDrawer('View someone’s work','Demo people · choose a person to try their workspace',`<div class="people-search"><input id="people-search" type="search" aria-label="Search people" placeholder="Name, email or department" autofocus></div><div class="row wrap" style="margin:14px 0">${button('Project colleagues','people-team','','active')}${button('All people','people-all')}</div><div id="people-results"></div>`);
  currentDrawerPeople=team;renderPeople('');$('#people-search').disabled=false;$('#people-search').focus();
 }
 let currentDrawerPeople=new Set();
 function renderPeople(query){const q=query.trim().toLowerCase(),s=state();const people=s.people.filter(p=>(q||peopleScope==='all'||currentDrawerPeople.has(p.id))&&(!q||`${p.name} ${p.email||''} ${p.department} ${p.id}`.toLowerCase().includes(q))).sort((a,b)=>Number(b.id===ui.person)-Number(a.id===ui.person)||a.name.localeCompare(b.name));$('#people-results').innerHTML=`<p class="small muted" role="status">${people.length} people · showing ${Math.min(25,people.length)}${people.length>25?' · Search to narrow the list':''}</p><div class="people-list">${people.slice(0,25).map(p=>`<button type="button" class="lookup-result" data-action="choose-person" data-id="${esc(p.id)}"><strong>${esc(p.name)}${p.id===ui.person?' · Current':''}</strong><small>${esc(p.department)} · ${esc(p.email||p.role||p.id)}</small></button>`).join('')||empty('No people match this search.')}</div>`;}
 function openWorkProjects(){const s=state(),ids=new Set(s.tasks.filter(t=>t.ownerIds.includes(ui.person)).map(t=>t.projectId));showDrawer('Filter your projects','Projects with work assigned to you',lookup('Project','workProject',projectItems(s.projects.filter(p=>ids.has(p.id))),ui.workProject?[ui.workProject]:[],{emptyText:'Search projects',change:id=>{ui.workProject=id;ui.workLimit=10;closeDrawer();render();}}));$('#detail-form details').open=true;}
 function planningFields(t){const choices=tasksFor(state(),t.projectId).filter(x=>x.id!==t.id).map(x=>({id:x.id,label:x.title,detail:x.workstream}));return `<div class="form-grid">${selectField('Task type','kind',['Assessment','Execution','Test','Approval'],t.kind)}${field('Estimated duration','duration',t.duration,'number')}${selectField('Duration basis','durationBasis',['Working Days','Calendar Days'],t.durationBasis)}</div>${lookup('Prerequisite tasks','predecessorIds',choices,t.predecessorIds,{multiple:true,emptyText:'Change prerequisites'})}${lookup('Source assessments','sourceAssessmentIds',choices.filter(x=>state().tasks.find(t=>t.id===x.id).kind==='Assessment'),t.sourceAssessmentIds,{multiple:true,emptyText:'Change source assessments'})}`;}
 function taskSetup(t){return `<details class="detail-section"><summary>Dates, owners & task details</summary>${field('Task name','title',t.title)}<div class="form-grid">${field('Start date','start',t.start,'date')}${field('Due date','due',t.due,'date')}</div>${lookup('Owners','ownerIds',peopleItems(),t.ownerIds,{multiple:true,preferred:teamIds(t.projectId,t.ownerIds),emptyText:'Change owners'})}<details class="detail-section"><summary>Planning details</summary><div class="form-grid">${selectField('Work area','workstream',[...new Set([...state().people.map(p=>p.department),'Other','Unassigned',t.workstream])],t.workstream)}${selectField('Phase','phase',STAGES,t.phase)}${selectField('Priority','priority',['Normal','High','Low'],t.priority)}</div>${field('Work brief','brief',t.brief,'textarea')}${planningFields(t)}</details></details>`;}
 function openTask(id){
  const s=state(),t=s.tasks.find(t=>t.id===id);if(!t)return;taskDraft=null;
  const waiting=t.predecessorIds.map(id=>s.tasks.find(x=>x.id===id)).filter(x=>x&&!done(x));
  const linked=t.sourceAssessmentIds.map(id=>s.tasks.find(x=>x.id===id)).filter(Boolean);
  const result=t.kind==='Assessment'?selectField('Assessment result','assessmentDecision',[['','Not recorded'],'Needs Information','Further Work Required','No Further Work'],t.assessmentDecision):t.kind==='Test'?selectField('Test result','testResult',['Not Reported','Pass','Fail','Conditional'],t.testResult):t.kind==='Approval'?`<div class="form-grid">${selectField('ECN status','approvalStatus',['Not Submitted','In Review','Returned','Approved'],t.approvalStatus||'Not Submitted')}${field('Decision date','approvalDate',t.approvalDate,'date')}</div>`:'';
  const resultTitle={Assessment:'Assessment result',Test:'Test result',Approval:'ECN status'}[t.kind];
  const resultValue=t.kind==='Assessment'?t.assessmentDecision:t.kind==='Test'?t.testResult:t.approvalStatus;
  const other=t.ownerIds.filter(id=>id!==ui.person&&!t.completedBy.includes(id));
  showDrawer(t.title,`${t.projectId} · ${project(s,t.projectId)?.name}`,`<div class="task-summary"><div class="row wrap">${badge(taskStatus(t,s.scenarioDate))}${t.priority==='High'?badge('High priority'):''}<span class="small muted">Due ${date(t.due)}</span></div><p class="text-block">${esc(t.brief||'No work brief added.')}</p><span class="small muted">${esc(t.ownerIds.map(name).join(', ')||'Unassigned')}</span>${closedHint(project(s,t.projectId))}</div>${waiting.length?`<div class="notice">Waiting for: ${waiting.map(x=>button(x.title,'task',x.id,'link')).join(' · ')}</div>`:''}${field(t.kind==='Assessment'?'Assessment findings':'Latest update','outcome',t.outcome,'textarea')}<label class="completion-line">${t.ownerIds.includes(ui.person)?`<input type="checkbox" name="confirmOwnPart" ${t.completedBy.includes(ui.person)?'checked':''}> My part is complete`:''}</label>${other.length?`<p class="small muted">Also assigned to ${esc(other.map(name).join(', '))}.</p>`:''}${result?`<details class="detail-section" ${t.kind==='Approval'?'open':''}><summary>${esc(resultTitle)}${resultValue?' · '+esc(resultValue):''}</summary>${result}</details>`:''}${t.deliverableId?`<div style="margin-top:16px">${button('Open document','document',t.deliverableId)}</div>`:''}${linked.length?`<div class="notice" style="margin-top:16px">Based on ${linked.map(x=>button(x.title,'task',x.id,'link')).join(' · ')}</div>`:''}${taskSetup(t)}${t.kind==='Assessment'&&editAllowed()?`<details class="detail-section"><summary>Follow-up work</summary>${button('Save & plan follow-up','simple-follow-up',id)}</details>`:''}<details class="detail-section"><summary>History</summary>${historyView(s.history.filter(x=>x.entity==='task'&&x.entityId===id))}</details>`,{save:'Save update'});
  formSubmit(async f=>{await operation('updateTask',id,taskValues(f,t));closeDrawer();});
 }
 function taskValues(f,t){const v={};for(const k of ['title','start','due','workstream','phase','priority','brief','outcome','assessmentDecision','testResult','approvalStatus','approvalDate','kind','durationBasis'])if(f.has(k))v[k]=f.get(k);v.ownerIds=inputValues('ownerIds');v.predecessorIds=inputValues('predecessorIds');v.sourceAssessmentIds=inputValues('sourceAssessmentIds');v.duration=Number(f.get('duration'));if(t.ownerIds.includes(ui.person)&&v.ownerIds.includes(ui.person))v.confirmOwnPart=f.has('confirmOwnPart');return v;}
 function openNewTask(pid='',sources=[]){
  const s=state(),source=s.tasks.find(t=>t.id===sources[0]),context=source?.projectId||pid||(ui.page==='projects'?ui.projectId:'')||ui.workProject;
  const ps=currentProjects(),selected=context||(ps.length===1?ps[0].id:'');
  const def=taskDefaults(s,{projectId:selected,actorId:ui.person,sourceAssessmentIds:sources});
  taskDraft={projectId:selected,sources,ownerEdited:false,defaults:def};
  showDrawer(source?'Plan the follow-up work':'Add task',source?`${source.projectId} · ${source.title}`:'Choose the project, name the work, set the due date.',lookup('Project','projectId',projectItems(context?[project(s,context)]:ps),selected?[selected]:[],{emptyText:'Search my active projects',change:changeTaskProject})+field('Task name','title','')+field('Due date','due',s.scenarioDate,'date')+lookup('Owners','ownerIds',peopleItems(),def.ownerIds,{multiple:true,preferred:teamIds(selected),emptyText:'Change owners'})+`<details class="detail-section"><summary>More details</summary>${field('Start date','start',s.scenarioDate,'date')}${field('Work brief','brief',source?`Based on: ${source.title}\n${source.outcome}`:'','textarea')}</details>`,{save:'Create task'});
  if(!selected){$('#detail-form details.lookup-menu').open=true;}formSubmit(async f=>{
   const pId=inputValues('projectId')[0];if(!pId)throw new Error('Choose a project for this task.');
   const values={projectId:pId,title:f.get('title'),due:f.get('due'),start:f.get('start'),brief:f.get('brief'),ownerIds:inputValues('ownerIds'),sourceAssessmentIds:sources};
   const r=await operation('createTask','',values);taskDraft=null;closeDrawer();openTask(r.id);
  });
 }
 function changeTaskProject(pid){if(!taskDraft)return;taskDraft.projectId=pid;const def=taskDefaults(state(),{projectId:pid,actorId:ui.person,sourceAssessmentIds:taskDraft.sources});const p=pickers.get('ownerIds');p.values=def.ownerIds;p.preferred=teamIds(pid);updateLookup('ownerIds');}
 function issueButtons(i){const s=state(),pm=i.verifierId||project(s,i.projectId)?.leadId,remaining=s.actions.filter(a=>a.issueId===i.id&&!['Done','Cancelled'].includes(a.status)).length;
  if(!editAllowed()||i.status==='Closed')return '';
  if(i.status==='Pending Verification')return pm===ui.person?button('Review resolution','review-issue',i.id,'primary'):`<span class="pill blue">Waiting for ${esc(name(pm))}</span>`;
  if([i.ownerId,pm].includes(ui.person))return remaining?`<span class="small muted">${remaining} recovery actions remaining</span>`:button('Resolve issue','resolve-issue',i.id,'primary');return '';
 }
 function openResolution(id,review=false){const s=state(),i=s.issues.find(x=>x.id===id);if(!i)return;const verifier=i.verifierId||project(s,i.projectId)?.leadId,canClose=verifier===ui.person;
  showDrawer(review?'Review resolution':'Resolve issue',`${id} · ${i.title}`,`<p class="text-block">${esc(i.details)}</p><div style="margin-top:16px">${field('Resolution','resolution',i.resolution||'','textarea')}</div><details class="detail-section"><summary>Cause & prevention</summary>${field('Root cause','rootCause',i.rootCause||'','textarea')}${field('Prevent recurrence','prevention',i.prevention||'','textarea')}</details>${review?field('Follow-up needed (if returned)','returnReason','','textarea')+button('Return for follow-up','return-resolution',id,'quiet'):!canClose?`<p class="small muted">${esc(name(verifier))} will confirm the resolution.</p>`:''}`,{save:canClose?'Confirm closure':'Submit resolution'});
  formSubmit(async f=>{await operation('updateIssue',id,{resolution:f.get('resolution'),rootCause:f.get('rootCause'),prevention:f.get('prevention'),status:canClose?'Closed':'Pending Verification'});ctx.openIssue(id);});
 }
 function openAction(id){const s=state(),a=s.actions.find(x=>x.id===id),i=s.issues.find(x=>x.id===a?.issueId);if(!a||!i)return;showDrawer(a.title,`${i.projectId} · ${i.title}`,`<div class="task-summary"><p class="small muted">${esc(name(a.ownerId))} · Due ${date(a.due)}</p><p class="text-block">${esc(i.impact)}</p></div>${field('Latest result','result',a.result,'textarea')}<label class="completion-line"><input type="checkbox" name="finished" ${a.status==='Done'?'checked':''}> My action is complete</label><details class="detail-section"><summary>Dates, owner & evidence</summary>${field('Due date','due',a.due,'date')}${lookup('Owner','ownerId',peopleItems(),[a.ownerId],{preferred:teamIds(i.projectId,[a.ownerId]),emptyText:'Change owner'})}${field('Evidence link','evidenceUrl',a.evidenceUrl,'url')}</details>`,{save:'Save update'});formSubmit(async f=>{await operation('updateAction',id,{result:f.get('result'),due:f.get('due'),ownerId:inputValues('ownerId')[0],evidenceUrl:f.get('evidenceUrl'),status:f.has('finished')?'Done':a.status==='Done'?'In Progress':a.status});closeDrawer();});}
 function openSettings(){showDrawer('Demo settings','Local simulation settings',`<p class="text-block">${state().people.length.toLocaleString()} people · ${state().projects.length} projects · ${state().tasks.length.toLocaleString()} tasks. Additional records are synthetic examples.</p>${selectField('Access preview','previewMode',[['contributor','Can update'],['viewer','Read only']],ui.mode==='viewer'?'viewer':'contributor')}<p class="small muted">These settings simulate the experience; they are not company sign-in.</p>`,{save:'Apply'});$('#f-previewMode').disabled=false;if(!editAllowed())$('.drawer-foot').insertAdjacentHTML('beforeend','<button type="submit" form="detail-form" class="primary">Apply</button>');formSubmit(f=>{ui.mode=f.get('previewMode');localStorage.setItem('autopm-mode',ui.mode);closeDrawer();render();});}
 function handleAction(action,id){
  if(action==='choose-person'){ui.person=id;ui.workProject='';ui.workQuery='';ui.workLimit=10;ui.actionLimit=8;ui.issueLimit=6;localStorage.setItem('autopm-person',id);closeDrawer();render();}
  else if(action==='people')openPeople();
  else if(action==='people-team'||action==='people-all'){peopleScope=action==='people-team'?'team':'all';renderPeople($('#people-search').value);}
  else if(action==='work-projects')openWorkProjects();
  else if(action==='clear-work-project'){ui.workProject='';ui.workLimit=10;render();}
  else if(action==='more-work'){ui.workLimit+=10;render();}
  else if(action==='jump-actions')document.querySelector('[data-action="action"]')?.closest('.panel')?.scrollIntoView({behavior:'smooth',block:'start'});
  else if(action==='more-actions'){ui.actionLimit=(ui.actionLimit||8)+8;render();}
  else if(action==='more-issues'){ui.issueLimit=(ui.issueLimit||6)+6;render();}
  else if(action==='demo-settings')openSettings();
  else if(action==='resolve-issue')openResolution(id);
  else if(action==='review-issue')openResolution(id,true);
  else if(action==='return-resolution')return (async()=>{const reason=$('#f-returnReason').value.trim();if(!reason)throw new Error('Describe what still needs to be resolved.');await operation('updateIssue',id,{status:'In Recovery',returnReason:reason});ctx.openIssue(id);return true;})();
  else if(action==='simple-follow-up')return (async()=>{const t=state().tasks.find(t=>t.id===id);await operation('updateTask',id,taskValues(new FormData($('#detail-form')),t));openNewTask(t.projectId,[id]);return true;})();
  else if(action==='lookup-select'||action==='lookup-remove'){const at=id.indexOf('|'),key=id.slice(0,at),value=id.slice(at+1),p=pickers.get(key);if(action==='lookup-remove')p.values=p.values.filter(x=>x!==value);else p.values=p.multiple?[...new Set([...p.values,value])]:[value];updateLookup(key);if(!p.multiple)$(`[data-picker="${key}"] details`).open=false;p.change?.(p.values[0]);}
  else return false;return true;
 }
 function handleInput(e){const el=e.target;if(el.dataset.lookup){$(`[data-picker="${el.dataset.lookup}"] [data-results]`).innerHTML=lookupResults(el.dataset.lookup,el.value);}if(el.id==='people-search')renderPeople(el.value);if(el.id==='mywork-search'){const start=el.selectionStart;ui.workQuery=el.value;ui.workLimit=10;clearTimeout(window.workTimer);window.workTimer=setTimeout(()=>{render();$('#mywork-search')?.focus();$('#mywork-search')?.setSelectionRange(start,start);},120);}}
 return {renderMyWork,openTask,openNewTask,openPeople,openAction,issueButtons,handleAction,handleInput};
}
